import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong();
        StringBuilder sb = new StringBuilder();
        int c = read();
        for (int w = 0; w < n; w++) {
            while (c != -1 && c <= ' ') c = read();
            // Stream the word: a run of L equal letters needs floor(L / 2) replacements.
            long edits = 0;
            int prev = -1, run = 0;
            while (c > ' ') {
                if (c == prev) run++;
                else {
                    edits += run / 2;
                    prev = c;
                    run = 1;
                }
                c = read();
            }
            edits += run / 2;
            if (w > 0) sb.append(' ');
            sb.append(edits);
        }
        System.out.println(sb);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n := int(nextInt())
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	for k := 0; k < n; k++ {
		for pos < len(data) && data[pos] <= ' ' {
			pos++
		}
		// A run of L equal letters needs floor(L / 2) replacements.
		edits := 0
		for pos < len(data) && data[pos] > ' ' {
			j := pos + 1
			for j < len(data) && data[j] == data[pos] {
				j++
			}
			edits += (j - pos) / 2
			pos = j
		}
		if k > 0 {
			w.WriteByte(' ')
		}
		w.WriteString(strconv.Itoa(edits))
	}
	w.WriteByte('\n')
}
